const fs = require('fs');
const path = require('path');
const t = fs.readFileSync(path.join(__dirname, '../figma-extract/05-ops-platform-nodes.json'), 'utf8');
const ids = ['243:7114', '243:7143', '243:7175', '243:7207', '243:7253', '243:7299'];
ids.forEach(function (id) {
  const start = t.indexOf('"id":  "' + id + '"');
  if (start < 0) {
    console.log('--- ' + id + ' NOT FOUND');
    return;
  }
  const nextId = t.indexOf('"id":  "243:', start + 20);
  const chunk = t.slice(start, nextId > 0 ? nextId : start + 12000);
  const re = /characters=\s*([^;]+);/g;
  const set = new Set();
  let m;
  while ((m = re.exec(chunk))) set.add(m[1].replace(/\\n/g, '\n'));
  console.log('=== ' + id + ' ===');
  console.log([...set].join('\n---\n'));
});

const fs = require('fs');
const path = require('path');
const file = process.argv[2];
if (!file) { console.error('usage: node _parse-frame-text.js <frame.json>'); process.exit(1); }
const j = JSON.parse(fs.readFileSync(path.resolve(file), 'utf8'));
const out = [];
function walk(n) {
  if (!n) return;
  if (n.type === 'TEXT' && n.characters) out.push({ id: n.id, name: n.name, text: n.characters });
  (n.children || []).forEach(function (c) {
    if (typeof c === 'object') walk(c);
  });
}
walk(j);
out.forEach(function (x) { console.log(x.id + ' | ' + x.name + ' | ' + JSON.stringify(x.text)); });

