input.contents:
/**
 * 用户端极简对话页
 * 只承载聊天产品自然入口：智能体切换、模型选择、会话 Skills、引用来源、文件结果、反馈。
 */
(function (global) {
  var STORAGE_KEY = 'proto_user_chat_state';
  var DEFAULT_MODEL = '旗舰模型';
  var LEGACY_MODEL_PATTERN = /DeepSeek|Qwen|OpenAI|GPT-/i;

  var MODELS = ['标准模型', '增强模型', '专业模型', '旗舰模型'];

  var AGENTS = [
    {
      id: 'agt_ocean',
      name: '海能·智能助手',
      group: '企业智能体',
      intro: '您好！我是基于海能平台搭建的企业 AI 助手，可结合企业知识库为您解答党建、财务、QHSE、勘探开发、钻完井等业务问题，很高兴为您服务。',
      suggestions: ['介绍一下海能平台能力', '帮我总结今天的重点工作', '解释一下这个报告并给出修复步骤'],
      sources: ['企业制度库', '企业知识库', '历史问答沉淀'],
      output: '结构化回答'
    },
    {
      id: 'agt_travel',
      name: '差旅报销助手',
      group: '企业智能体',
      intro: '我可以帮您解答公司差旅报销、费用标准、材料要求等问题，并整理报销说明与材料清单。',
      suggestions: ['报销流程有哪些', '差旅发票缺失怎么办', '帮我写一段报销说明'],
      sources: ['财务报销制度', '差旅操作手册', '常见问题库'],
      output: '报销说明'
    },
    {
      id: 'agt_jsa',
      name: 'jsa文档生成',
      group: '企业智能体',
      intro: '我可以根据作业信息生成JSA作业安全分析表，并整理潜在危害、控制措施和责任人。',
      suggestions: ['帮我生成空压机检修JSA', '补全这份JSA的控制措施', '把作业步骤整理成表格'],
      sources: ['JSA标准模板', 'QHSE制度库', '历史作业安全分析表'],
      output: 'DOCX 文档'
    },
    {
      id: 'agt_party',
      name: '党建智能助手',
      group: '企业智能体',
      intro: '我可以协助整理党建材料、会议纪要、学习记录和常用通知文案。',
      suggestions: ['生成一份会议纪要', '把这段文字改成通知', '提炼学习材料要点'],
      sources: ['党建材料库', '通知模板库', '会议纪要样例'],
      output: '文案草稿'
    },
    {
      id: 'agt_shift',
      name: '值班安排助手',
      group: '企业智能体',
      intro: '我可以查询值班记录、整理排班信息，并生成交接事项摘要。',
      suggestions: ['帮我查明天的值班记录', '汇总本周交接异常', '生成一份值班交接摘要'],
      sources: ['值班台账', '排班表', '交接记录'],
      output: '表格回答'
    },
    {
      id: 'agt_safe',
      name: '钻完井安全',
      group: '企业智能体',
      intro: '我可以围绕钻完井安全制度、现场风险和整改建议提供问答与材料整理。',
      suggestions: ['解释这条安全要求', '找出这段记录里的风险点', '生成整改建议'],
      sources: ['钻完井安全制度', '现场风险案例库', 'QHSE知识库'],
      output: '风险清单'
    },
    {
      id: 'agt_report',
      name: '钻完井报告助手',
      group: '企业智能体',
      intro: '我可以根据日报、完井资料和附件生成标准化报告，并保留引用来源。',
      suggestions: ['生成完工报告', '提取日报关键风险', '把附件整理成报告目录'],
      sources: ['钻完井资料库', '日报归档', '标准报告模板'],
      output: 'DOCX 文档'
    },
    {
      id: 'agt_waste',
      name: '废旧物资清单助手',
      group: '企业智能体',
      intro: '我可以读取表格或图片材料，整理废旧物资清单并提示缺失字段。',
      suggestions: ['整理这份废旧物资清单', '找出缺少编号的物资', '生成核对表'],
      sources: ['物资目录', '历史清单', '字段映射规则'],
      output: 'Excel 表格'
    },
    {
      id: 'agt_building',
      name: '智慧楼宇助手',
      group: '企业智能体',
      intro: '我可以查询楼宇设备、工单处理和常见运维问题。',
      suggestions: ['空调报修流程是什么', '生成巡检记录摘要', '解释这个设备告警'],
      sources: ['楼宇设备台账', '运维工单', '巡检规范'],
      output: '运维建议'
    },
    {
      id: 'agt_explore',
      name: '勘探井资料助手',
      group: '企业智能体',
      intro: '我可以辅助检索勘探井资料、整理关键信息和形成摘要。',
      suggestions: ['提取这份资料的重点', '整理井史摘要', '列出需要补充的材料'],
      sources: ['勘探井资料库', '项目档案', '历史摘要'],
      output: '资料摘要'
    }
  ];

  var ICONS = {
    bot: '<svg viewBox="0 0 32 32" width="32" height="32" fill="none" aria-hidden="true"><rect width="32" height="32" rx="10" fill="#eef4ff"/><path d="M8 22c3-4 6-6 8-6s5 2 8 6" stroke="#003da6" stroke-width="1.6" stroke-linecap="round"/><circle cx="16" cy="13" r="3" fill="#003da6"/></svg>',
    copy: '<svg viewBox="0 0 20 20" width="18" height="18" fill="none" aria-hidden="true"><rect x="6.5" y="6.5" width="9" height="9" rx="1.5" stroke="currentColor" stroke-width="1.4"/><path d="M13.5 6.5V5a1.5 1.5 0 00-1.5-1.5H5A1.5 1.5 0 003.5 5v7a1.5 1.5 0 001.5 1.5h1.5" stroke="currentColor" stroke-width="1.4"/></svg>',
    retry: '<svg viewBox="0 0 20 20" width="18" height="18" fill="none" aria-hidden="true"><path d="M4 10a6 6 0 0110.2-4.2M16 10a6 6 0 01-10.2 4.2" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/><path d="M14.5 3.5V6h-2.5M5.5 16.5V14H8" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    like: '<svg viewBox="0 0 20 20" width="18" height="18" fill="none" aria-hidden="true"><path d="M10 17s-6-3.6-6-8.2c0-2.2 1.8-3.8 4-3.8 1.3 0 2 .7 2 .7s.7-.7 2-.7c2.2 0 4 1.6 4 3.8C16 13.4 10 17 10 17z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>',
    feedback: '<svg viewBox="0 0 20 20" width="18" height="18" fill="none" aria-hidden="true"><path d="M4 5.5h12v7H7.5L5 15V5.5z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>',
    file: '<svg viewBox="0 0 20 20" width="18" height="18" fill="none" aria-hidden="true"><path d="M6 3.5h5.5L14 6v10.5H6V3.5z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="M11.5 3.5V6H14" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>',
    download: '<svg viewBox="0 0 20 20" width="18" height="18" fill="none" aria-hidden="true"><path d="M10 4v8M10 12l-3-3M10 12l3-3M5 16h10" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>'
  };

  var state = null;
  var els = {};
  var opts = {};

  function normalizeModel(model) {
    if (!model || LEGACY_MODEL_PATTERN.test(model) || MODELS.indexOf(model) < 0) {
      return DEFAULT_MODEL;
    }
    return model;
  }

  function loadState() {
    try {
      var saved = JSON.parse(sessionStorage.getItem(STORAGE_KEY) || '{}');
      return {
        agentId: saved.agentId || 'agt_ocean',
        model: normalizeModel(saved.model)
      };
    } catch (e) {
      return { agentId: 'agt_ocean', model: DEFAULT_MODEL };
    }
  }

  function saveState() {
    try { sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) {}
  }

  function agentById(id) {
    return AGENTS.find(function (agent) { return agent.id === id; }) || AGENTS[0];
  }

  function activeAgent() {
    return agentById(state.agentId);
  }

  function escapeHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (ch) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch];
    });
  }

  function getSkillNames() {
    if (opts.sessionSkills && typeof opts.sessionSkills.getActiveNames === 'function') {
      return opts.sessionSkills.getActiveNames();
    }
    return [];
  }

  function miniAvatarHtml() {
    return '<div class="aioq-mini-avatar" aria-hidden="true">' + ICONS.bot + '</div>';
  }

  function flashButton(btn) {
    if (!btn) return;
    btn.classList.add('is-active');
    setTimeout(function () { btn.classList.remove('is-active'); }, 900);
  }

  function renderAgentList() {
    var query = (els.agentSearch.value || '').trim().toLowerCase();
    var visible = AGENTS.filter(function (agent) {
      return !query || [agent.name, agent.intro].join(' ').toLowerCase().indexOf(query) >= 0;
    });
    els.agentList.innerHTML = visible.map(function (agent) {
      return '<button type="button" class="aioq-agent-link ' + (agent.id === state.agentId ? 'active' : '') + '" data-agent-id="' + agent.id + '">' +
        escapeHtml(agent.name) +
      '</button>';
    }).join('');
  }

  function renderWelcome() {
    var agent = activeAgent();
    els.welcomeName.textContent = agent.name;
    els.welcomeDesc.textContent = agent.intro;
    els.promptSuggestions.innerHTML = agent.suggestions.map(function (text) {
      return '<button type="button" data-prompt="' + escapeHtml(text) + '">' + escapeHtml(text) + '</button>';
    }).join('');
    renderCapabilityPanel();
    renderAgentList();
  }

  function renderModelMenu() {
    els.modelLabel.textContent = state.model;
    els.btnModel.setAttribute('aria-expanded', els.modelMenu.classList.contains('hidden') ? 'false' : 'true');
    els.modelMenu.innerHTML = MODELS.map(function (model) {
      return '<button type="button" data-model="' + escapeHtml(model) + '" class="' + (model === state.model ? 'active' : '') + '">' +
        escapeHtml(model) +
      '</button>';
    }).join('');
  }

  function renderCapabilityPanel() {
    var agent = activeAgent();
    var skillNames = getSkillNames();
    els.capabilityContent.innerHTML =
      '<div class="aioq-cap-row"><span>当前智能体</span><strong>' + escapeHtml(agent.name) + '</strong></div>' +
      '<div class="aioq-cap-row"><span>当前模型</span><strong>' + escapeHtml(state.model) + '</strong></div>' +
      '<div class="aioq-cap-row"><span>会话 Skills</span><strong>' + escapeHtml(skillNames.length ? skillNames.join('、') : '未临时增强') + '</strong></div>' +
      '<div class="aioq-cap-list"><span>回答来源</span>' +
        agent.sources.map(function (source) { return '<em>' + escapeHtml(source) + '</em>'; }).join('') +
      '</div>';
  }

  function positionModelMenu() {
    if (!els.btnModel || !els.modelMenu) return;
    var rect = els.btnModel.getBoundingClientRect();
    var menuWidth = 206;
    var left = Math.max(16, Math.min(rect.left, window.innerWidth - menuWidth - 16));
    els.modelMenu.style.top = Math.round(rect.bottom + 8) + 'px';
    els.modelMenu.style.left = left + 'px';
  }

  function positionCapabilityPanel() {
    if (!els.btnCapability || !els.capabilityPanel) return;
    var rect = els.btnCapability.getBoundingClientRect();
    var panelWidth = 340;
    var left = Math.max(16, Math.min(rect.left, window.innerWidth - panelWidth - 16));
    els.capabilityPanel.style.left = left + 'px';
    els.capabilityPanel.style.bottom = Math.max(16, window.innerHeight - rect.top + 12) + 'px';
  }

  function selectAgent(id) {
    state.agentId = id;
    saveState();
    clearChat();
    renderWelcome();
  }

  function clearChat() {
    els.chatMsgs.innerHTML = '';
    els.welcomePanel.classList.remove('hidden');
  }

  function appendMessage(html) {
    els.welcomePanel.classList.add('hidden');
    els.chatMsgs.insertAdjacentHTML('beforeend', html);
    if (els.stageScroll) {
      els.stageScroll.scrollTop = els.stageScroll.scrollHeight;
    }
  }

  function buildAnswer(prompt) {
    var agent = activeAgent();
    var skills = getSkillNames();
    var usedSkills = skills.length ? skills.join('、') : '默认问答能力';
    var introSnippet = agent.intro.replace(/^您好！|^Hi，大家好！/, '');
    return '<article class="aioq-answer">' +
      '<div class="aioq-answer-title">' +
        miniAvatarHtml() +
        '<strong>' + escapeHtml(agent.name) + '</strong>' +
      '</div>' +
      '<div class="aioq-thinking"><span></span><strong>思考完成</strong><button type="button" data-toggle-thinking aria-label="展开思考过程">⌄</button></div>' +
      '<div class="aioq-thinking-detail">' +
        '<p>首先确认用户问题：“' + escapeHtml(prompt) + '”。本轮使用 ' + escapeHtml(state.model) + '，并结合 ' + escapeHtml(usedSkills) + ' 进行回答。</p>' +
      '</div>' +
      '<div class="aioq-answer-body">' +
        '<p>根据您的问题，我会直接基于当前智能体能力和可用来源进行说明，避免把后台配置、审核、派单等运营信息暴露到用户端。</p>' +
        '<p>如果涉及文档生成，我会在回答下方给出文件卡；如果涉及来源，我会保留“引用段落 / 查看原文”的入口，方便您核对。</p>' +
        '<p><strong>简要结论：</strong>' + escapeHtml(introSnippet) + '</p>' +
      '</div>' +
      '<div class="aioq-citations">' +
        '<button type="button" class="active">引用段落</button>' +
        '<button type="button" data-view-source>查看原文</button>' +
        '<span>' + escapeHtml(agent.sources[0]) + ' · 已命中 3 段</span>' +
      '</div>' +
      '<div class="aioq-file-card">' +
        '<span class="aioq-file-icon">' + ICONS.file + '</span>' +
        '<div><strong>' + escapeHtml(agent.output) + '结果.docx</strong><small>文件生成完成</small></div>' +
        '<button type="button" data-download-file title="下载" aria-label="下载">' + ICONS.download + '</button>' +
      '</div>' +
      '<div class="aioq-answer-actions">' +
        '<button type="button" data-copy-answer title="复制" aria-label="复制">' + ICONS.copy + '</button>' +
        '<button type="button" data-retry-answer title="重试" aria-label="重试">' + ICONS.retry + '</button>' +
        '<button type="button" data-like-answer title="点赞" aria-label="点赞">' + ICONS.like + '</button>' +
        '<button type="button" data-open-feedback title="反馈" aria-label="反馈">' + ICONS.feedback + '</button>' +
      '</div>' +
    '</article>';
  }

  function sendChat() {
    var text = els.chatInput.value.trim();
    if (!text) return;
    appendMessage('<div class="aioq-user-bubble"><span>' + escapeHtml(text) + '</span></div>');
    appendMessage(buildAnswer(text));
    els.chatInput.value = '';
  }

  function toggle(el) {
    el.classList.toggle('hidden');
  }

  function closeFloatingPanels() {
    els.modelMenu.classList.add('hidden');
    els.capabilityPanel.classList.add('hidden');
    if (els.btnModel) els.btnModel.setAttribute('aria-expanded', 'false');
  }

  function openFeedback() {
    els.feedbackModal.classList.remove('hidden');
  }

  function closeFeedback() {
    els.feedbackModal.classList.add('hidden');
  }

  function toggleSidebar() {
    if (!els.root) return;
    els.root.classList.toggle('is-sidebar-collapsed');
    var collapsed = els.root.classList.contains('is-sidebar-collapsed');
    if (els.btnCollapseSidebar) {
      els.btnCollapseSidebar.setAttribute('aria-label', collapsed ? '展开侧栏' : '收起侧栏');
      els.btnCollapseSidebar.setAttribute('title', collapsed ? '展开侧栏' : '收起侧栏');
    }
  }

  function toggleAgentMenu() {
    if (!els.agentMenuBlock || !els.btnToggleAgents) return;
    var collapsed = els.agentMenuBlock.classList.toggle('is-agents-collapsed');
    els.btnToggleAgents.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
  }

  function bindEvents() {
    els.agentSearch.addEventListener('input', renderAgentList);
    els.agentList.addEventListener('click', function (event) {
      var btn = event.target.closest('[data-agent-id]');
      if (btn) selectAgent(btn.dataset.agentId);
    });
    els.btnNewChat.addEventListener('click', function () {
      clearChat();
      renderWelcome();
    });
    if (els.btnCollapseSidebar) {
      els.btnCollapseSidebar.addEventListener('click', function (event) {
        event.stopPropagation();
        toggleSidebar();
      });
    }
    if (els.btnToggleAgents) {
      els.btnToggleAgents.addEventListener('click', function (event) {
        event.stopPropagation();
        toggleAgentMenu();
      });
    }
    els.btnModel.addEventListener('click', function (event) {
      event.stopPropagation();
      els.capabilityPanel.classList.add('hidden');
      var opening = els.modelMenu.classList.contains('hidden');
      toggle(els.modelMenu);
      renderModelMenu();
      if (opening) positionModelMenu();
    });
    els.modelMenu.addEventListener('click', function (event) {
      var btn = event.target.closest('[data-model]');
      if (!btn) return;
      state.model = btn.dataset.model;
      saveState();
      renderModelMenu();
      renderCapabilityPanel();
      els.modelMenu.classList.add('hidden');
      els.btnModel.setAttribute('aria-expanded', 'false');
    });
    els.btnCapability.addEventListener('click', function (event) {
      event.stopPropagation();
      els.modelMenu.classList.add('hidden');
      els.btnModel.setAttribute('aria-expanded', 'false');
      renderCapabilityPanel();
      positionCapabilityPanel();
      toggle(els.capabilityPanel);
    });
    els.btnCloseCapability.addEventListener('click', function () {
      els.capabilityPanel.classList.add('hidden');
    });
    els.promptSuggestions.addEventListener('click', function (event) {
      var btn = event.target.closest('[data-prompt]');
      if (!btn) return;
      els.chatInput.value = btn.dataset.prompt;
      els.chatInput.focus();
    });
    els.chatSend.addEventListener('click', sendChat);
    els.chatInput.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault();
        sendChat();
      }
    });
    els.chatMsgs.addEventListener('click', function (event) {
      if (event.target.closest('[data-toggle-thinking]')) {
        var answer = event.target.closest('.aioq-answer');
        var detail = answer && answer.querySelector('.aioq-thinking-detail');
        if (detail) detail.classList.toggle('hidden');
      }
      if (event.target.closest('[data-view-source]')) els.sourcePanel.classList.remove('hidden');
      if (event.target.closest('[data-download-file]')) flashButton(event.target.closest('[data-download-file]'));
      if (event.target.closest('[data-copy-answer]')) flashButton(event.target.closest('[data-copy-answer]'));
      if (event.target.closest('[data-retry-answer]')) flashButton(event.target.closest('[data-retry-answer]'));
      if (event.target.closest('[data-like-answer]')) {
        var likeBtn = event.target.closest('[data-like-answer]');
        likeBtn.classList.toggle('is-active');
      }
      if (event.target.closest('[data-open-feedback]')) openFeedback();
    });
    els.btnCloseSource.addEventListener('click', function () {
      els.sourcePanel.classList.add('hidden');
    });
    els.btnRetrySource.addEventListener('click', function () {
      els.sourcePanel.classList.add('hidden');
    });
    els.btnFeedbackEntry.addEventListener('click', openFeedback);
    els.btnCloseFeedback.addEventListener('click', closeFeedback);
    els.btnCancelFeedback.addEventListener('click', closeFeedback);
    els.btnSubmitFeedback.addEventListener('click', function () {
      closeFeedback();
    });
    els.btnVoice.addEventListener('click', function () {
      els.btnVoice.classList.add('is-recording');
